import { t } from '@lingui/core/macro';
import { activateLanguage, decimalText, pageLanguage } from './i18n';

describe('page language', () => {
  afterEach(() => { activateLanguage('en'); });

  it('reads the catalog the app names, and English without one', () => {
    expect(pageLanguage('de').code).toBe('de');
    expect(pageLanguage('pt_BR').code).toBe('pt_BR');
    expect(pageLanguage('pt-BR').tag).toBe('pt-BR');
    expect(pageLanguage('de_AT').code).toBe('de');
    expect(pageLanguage('zh_HK').code).toBe('zh_TW');
    expect(pageLanguage('zh').code).toBe('zh_CN');
    expect(pageLanguage('xx').code).toBe('en');
    expect(pageLanguage(null).code).toBe('en');
  });

  it('translates marked text once a language is active', () => {
    expect(t`Language`).toBe('Language');
    activateLanguage('de');
    expect(t`Language`).toBe('Sprache');
    expect(document.documentElement.lang).toBe('de');
  });

  it('words a printer model apart from an AI model', () => {
    activateLanguage('zh_CN');
    expect(t`Model`).toBe('模型');
    expect(t`Search models`).toBe('搜索模型');
    expect(t({ message: 'Model', context: 'printer' })).toBe('型号');
    expect(t({ message: 'Search models', context: 'printer' })).toBe('搜索型号');
  });

  it('writes a decimal the way the page language does', () => {
    expect(decimalText(0.4, 1, 2)).toBe('0.4');
    expect(decimalText(1, 1, 2)).toBe('1.0');
    activateLanguage('de');
    expect(decimalText(0.4, 1, 2)).toBe('0,4');
    expect(decimalText(0.25, 1, 2)).toBe('0,25');
  });

  it('words a printer\'s build plate apart from a project plate', () => {
    activateLanguage('th');
    expect(t`Plate`).toBe('เพลต');
    expect(t({ message: 'Plate', context: 'build plate' })).toBe('แผ่นฐานพิมพ์');
  });
});

// The printer panel's fixed words: its opening line and the composer's
// placeholder. Everything else the panel says, the model says. The model's
// instructions are in printerInstructions.ts.

import { t } from '@lingui/core/macro';
import type { PrinterSessionPayload } from './bridge/protocol';

// "0.4", "0.25", "1.0": two decimals, trailing zeros dropped down to one, as
// the printer profiles spell nozzle sizes.
export function numberText(value: number): string {
  let text = value.toFixed(2);
  while (text.length > 3 && text.endsWith('0')) text = text.slice(0, -1);
  return text;
}

// "0.2, 0.4, 0.6 and 0.8 mm"
export function sizesText(nozzles: number[]): string {
  const sizes = nozzles.map(numberText);
  return `${sizes.map((size, index) => (index === 0 ? '' : index + 1 === sizes.length ? ' and ' : ', ') + size).join('')} mm`;
}

// A likely answer, rather than a standing invitation.
// Shown only, never sent to the model, so it is translated; the opening below
// is the model's own first turn and stays English.
export function placeholder(session: PrinterSessionPayload): string {
  if (session.mode === 'connect') return t`Ask anything about connecting it`;
  return session.mode === 'add'
    ? t`e.g. "bambu a1 mini" or "not sure, the small one"`
    : t`e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"`;
}

// The panel's own first line, which the model is shown as having said. A
// trailing "Choices:" line is drawn as reply chips, as the model's are.
export function opening(session: PrinterSessionPayload): string {
  const printer = session.context.printer;
  const name = printer?.name || session.printerName || 'this printer';
  // Asking about the printer's LAN mode is no use while this computer has
  // nothing to reach it with; the notice under this line offers the plug-in.
  if (session.mode === 'connect' && printer?.provider === 'bambu' && printer.needsNetworkPlugin)
    return `To connect ${name}, JusPrin first needs Bambu’s network plug-in, which isn’t installed on this computer yet. ${name} already works for preparing prints.`;
  if (session.mode === 'connect')
    return printer?.provider === 'bambu'
      ? `Let’s connect ${name}. Is it turned on, in LAN mode, and on the same network as this computer?\nChoices: Yes, it is | How do I check?`
      : `Let’s connect ${name}. What address do you use to open it in a browser? It’s usually its IP address, like 192.168.1.20.`;
  if (session.mode === 'change') return `This is the ${name}. Tell me what changed on it, or ask anything about it.`;
  return (
    'Which printer do you have? Tell me the brand and model, or share a photo of its label. ' +
    "Not sure? Tell me what you know, and I'll help you find it."
  );
}
